//! `cargo xtask entailments emit|check`: render the cause-verb entailment table
//! (`crates/deckmaste_plugin/tables/entailments.ron`) the engine `include_str!`s
//! (`deckmaste_engine::entail`). The rows are the closed `VerbName` cause-verb
//! vocabulary, one CR-cited fact form each ([CR#701] keyword actions): the
//! normal form that makes Dies-matches-sacrifice structural.
//!
//! This table is the source of truth for the rows; `check` (run by CI) fails when
//! the committed file differs from the rendering, so a row edit here must land
//! with a regenerated file. Each row fixes the verb's fact form (master-form
//! `kind` plus the `from`/`to` zone coordinates) and the three caps a
//! cause-narrowed pattern inherits (`object`, `actor`, `amount`); the engine reads
//! only `verb`, `kind`, `from`, `to` and `amount`.
//!
//! Row citations: Sacrifice [CR#701.21a], Destroy [CR#701.8a], Discard
//! [CR#701.9a], Exile [CR#701.13a], Mill [CR#701.17a], Play [CR#701.18a], Fight
//! [CR#701.14a], Explore [CR#701.44a], Regenerate [CR#701.19a].
//! Fight's damage is noncombat damage dealt by the fighting creature; explore
//! reveals from the library and the card lands in hand or graveyard; an applied
//! regeneration shield's visible fact is the tap.

use std::fmt::Write as _;
use std::path::Path;
use std::path::PathBuf;

use anyhow::Context as _;
use clap::Args;
use clap::Subcommand;

#[derive(Debug, Args)]
pub struct EntailmentsArgs {
    #[command(subcommand)]
    command: EntailmentsCmd,
}

#[derive(Debug, Subcommand)]
enum EntailmentsCmd {
    /// Write the entailment table to `crates/deckmaste_plugin/tables/entailments.ron`.
    Emit,
    /// Fail when the committed entailment table differs from the rendering.
    Check,
}

/// One row: `(verb, kind, from, to, object, actor, amount, cite)`.
struct Row {
    verb: &'static str,
    kind: &'static str,
    from: Option<&'static str>,
    to: Option<&'static str>,
    object: bool,
    actor: bool,
    amount: bool,
    cite: &'static str,
}

const fn row(
    verb: &'static str,
    kind: &'static str,
    from: Option<&'static str>,
    to: Option<&'static str>,
    caps: (bool, bool, bool),
    cite: &'static str,
) -> Row {
    Row {
        verb,
        kind,
        from,
        to,
        object: caps.0,
        actor: caps.1,
        amount: caps.2,
        cite,
    }
}

const ROWS: [Row; 9] = [
    row(
        "Sacrifice",
        "ZoneChange",
        Some("Battlefield"),
        Some("Graveyard"),
        (true, true, false),
        "[CR#701.21a]",
    ),
    row(
        "Destroy",
        "ZoneChange",
        Some("Battlefield"),
        Some("Graveyard"),
        (true, false, false),
        "[CR#701.8a]",
    ),
    row(
        "Discard",
        "ZoneChange",
        Some("Hand"),
        Some("Graveyard"),
        (true, true, true),
        "[CR#701.9a]",
    ),
    row(
        "Exile",
        "ZoneChange",
        None,
        Some("Exile"),
        (true, false, false),
        "[CR#701.13a]",
    ),
    row(
        "Mill",
        "ZoneChange",
        Some("Library"),
        Some("Graveyard"),
        (true, true, false),
        "[CR#701.17a]",
    ),
    row(
        "Play",
        "ZoneChange",
        None,
        Some("Battlefield"),
        (true, true, false),
        "[CR#701.18a]",
    ),
    row(
        "Fight",
        "Damage",
        None,
        None,
        (true, false, true),
        "[CR#701.14a]",
    ),
    row(
        "Explore",
        "ZoneChange",
        Some("Library"),
        None,
        (true, true, false),
        "[CR#701.44a]",
    ),
    row(
        "Regenerate",
        "StateBecame:Tapped",
        None,
        None,
        (true, true, false),
        "[CR#701.19a]",
    ),
];

fn opt(zone: Option<&str>) -> String {
    zone.map_or_else(|| "None".to_owned(), |z| format!("Some({z})"))
}

/// The full text of `entailments.ron`.
#[must_use]
pub fn render() -> String {
    let mut out = String::from(
        "// GENERATED by `cargo xtask entailments emit` — do not edit by hand.\n\
         // CI runs `cargo xtask entailments check` against this file.\n\
         // Cause-verb entailments ([CR#701] keyword actions): each VerbName's fact form + inherited caps.\n\
         (\n    rows: [\n",
    );
    for r in &ROWS {
        writeln!(
            out,
            "        (verb: \"{}\", kind: \"{}\", from: {}, to: {}, object: {}, actor: {}, amount: {}, cite: \"{}\"),",
            r.verb,
            r.kind,
            opt(r.from),
            opt(r.to),
            r.object,
            r.actor,
            r.amount,
            r.cite
        )
        .expect("writing to a String cannot fail");
    }
    out.push_str("    ],\n)\n");
    out
}

fn table_path() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../deckmaste_plugin/tables/entailments.ron")
}

pub fn run(args: &EntailmentsArgs) -> anyhow::Result<()> {
    let path = table_path();
    match args.command {
        EntailmentsCmd::Emit => {
            std::fs::write(&path, render())
                .with_context(|| format!("writing {}", path.display()))?;
            println!("wrote {}", path.display());
        }
        EntailmentsCmd::Check => {
            let committed = std::fs::read_to_string(&path)
                .with_context(|| format!("reading {}", path.display()))?;
            anyhow::ensure!(
                committed == render(),
                "{} is stale; run `cargo xtask entailments emit`",
                path.display()
            );
        }
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The committed table is exactly the rendering: the gate CI runs as `check`.
    #[test]
    fn committed_table_equals_the_rendering() {
        let committed = std::fs::read_to_string(table_path()).expect("read entailments.ron");
        assert_eq!(committed, render());
    }

    #[test]
    fn verbs_are_unique() {
        let mut verbs: Vec<_> = ROWS.iter().map(|r| r.verb).collect();
        verbs.sort_unstable();
        verbs.dedup();
        assert_eq!(verbs.len(), ROWS.len());
    }
}
